<?php
use App\Models\{AdditionalChargeType,CommercialConfigurationEvent,CompanyPaymentMethod};
use function Livewire\Volt\{computed,layout,state};
layout('layouts.app');
state(['payment_id'=>null,'payment_type'=>'bank','display_name'=>'','provider'=>'','bank_name'=>'','account_name'=>'','account_number'=>'','phone_or_business_number'=>'','branch_name'=>'','currency'=>'TZS','instructions'=>'','payment_active'=>true,'sort_order'=>0,'show_on_quotation'=>true,'show_on_proforma'=>true,'show_on_invoice'=>true,'charge_type_id'=>null,'charge_name'=>'','charge_description'=>'','charge_active'=>true,'charge_sort_order'=>0]);
$paymentMethods=computed(fn()=>CompanyPaymentMethod::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->orderBy('sort_order')->orderBy('id')->get());
$chargeTypes=computed(fn()=>AdditionalChargeType::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->orderBy('sort_order')->orderBy('id')->get());
$audit=function($subject,string $event,array $metadata=[]){CommercialConfigurationEvent::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->create(['company_id'=>auth()->user()->company_id,'user_id'=>auth()->id(),'subject_type'=>$subject instanceof CompanyPaymentMethod?'payment_method':'charge_type','subject_id'=>$subject->id,'event'=>$event,'metadata'=>$metadata]);};
$resetPayment=function(){$this->payment_id=null;$this->payment_type='bank';$this->display_name=$this->provider=$this->bank_name=$this->account_name=$this->account_number=$this->phone_or_business_number=$this->branch_name=$this->instructions='';$this->currency='TZS';$this->payment_active=$this->show_on_quotation=$this->show_on_proforma=$this->show_on_invoice=true;$this->sort_order=0;};
$editPayment=function(int $id){$m=CompanyPaymentMethod::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->findOrFail($id);foreach(['type'=>'payment_type','display_name'=>'display_name','provider'=>'provider','bank_name'=>'bank_name','account_name'=>'account_name','account_number'=>'account_number','phone_or_business_number'=>'phone_or_business_number','branch_name'=>'branch_name','currency'=>'currency','instructions'=>'instructions','is_active'=>'payment_active','sort_order'=>'sort_order','show_on_quotation'=>'show_on_quotation','show_on_proforma'=>'show_on_proforma','show_on_invoice'=>'show_on_invoice'] as $field=>$state)$this->{$state}=$m->{$field}??'';$this->payment_id=$m->id;};
$savePayment=function(){abort_unless(auth()->user()->can('payment_methods.manage'),403);$data=$this->validate(['payment_type'=>'required|in:bank,mobile_money,cash,other','display_name'=>'required|string|max:255','provider'=>'nullable|string|max:255','bank_name'=>'nullable|string|max:255','account_name'=>'nullable|string|max:255','account_number'=>'nullable|string|max:255','phone_or_business_number'=>'nullable|string|max:255','branch_name'=>'nullable|string|max:255','currency'=>'required|string|max:10','instructions'=>'nullable|string|max:1000','payment_active'=>'boolean','sort_order'=>'integer|min:0','show_on_quotation'=>'boolean','show_on_proforma'=>'boolean','show_on_invoice'=>'boolean']);$values=['company_id'=>auth()->user()->company_id,'type'=>$data['payment_type'],'display_name'=>$data['display_name'],'provider'=>$data['provider']?:null,'bank_name'=>$data['bank_name']?:null,'account_name'=>$data['account_name']?:null,'account_number'=>$data['account_number']?:null,'phone_or_business_number'=>$data['phone_or_business_number']?:null,'branch_name'=>$data['branch_name']?:null,'currency'=>strtoupper($data['currency']),'instructions'=>$data['instructions']?:null,'is_active'=>$data['payment_active'],'sort_order'=>$data['sort_order'],'show_on_quotation'=>$data['show_on_quotation'],'show_on_proforma'=>$data['show_on_proforma'],'show_on_invoice'=>$data['show_on_invoice']];$m=$this->payment_id?CompanyPaymentMethod::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->findOrFail($this->payment_id):new CompanyPaymentMethod;$created=!$m->exists;$m->fill($values)->save();$this->audit($m,$created?'created':'edited',['type'=>$m->type,'display_name'=>$m->display_name,'is_active'=>$m->is_active]);$this->resetPayment();session()->flash('success',__('application.payment_method_saved_6b6db4ac'));};
$togglePayment=function(int $id){abort_unless(auth()->user()->can('payment_methods.manage'),403);$m=CompanyPaymentMethod::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->findOrFail($id);$m->update(['is_active'=>!$m->is_active]);$this->audit($m,$m->is_active?'activated':'deactivated',['display_name'=>$m->display_name]);};
$resetCharge=function(){$this->charge_type_id=null;$this->charge_name=$this->charge_description='';$this->charge_active=true;$this->charge_sort_order=0;};
$editCharge=function(int $id){$c=AdditionalChargeType::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->findOrFail($id);$this->charge_type_id=$c->id;$this->charge_name=$c->name;$this->charge_description=$c->description?:'';$this->charge_active=$c->is_active;$this->charge_sort_order=$c->sort_order;};
$saveCharge=function(){abort_unless(auth()->user()->can('additional_charge_types.manage'),403);$data=$this->validate(['charge_name'=>'required|string|max:255','charge_description'=>'nullable|string|max:1000','charge_active'=>'boolean','charge_sort_order'=>'integer|min:0']);$c=$this->charge_type_id?AdditionalChargeType::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->findOrFail($this->charge_type_id):new AdditionalChargeType;$created=!$c->exists;$c->fill(['company_id'=>auth()->user()->company_id,'name'=>$data['charge_name'],'description'=>$data['charge_description']?:null,'is_active'=>$data['charge_active'],'sort_order'=>$data['charge_sort_order']])->save();$this->audit($c,$created?'created':'edited',['name'=>$c->name,'is_active'=>$c->is_active]);$this->resetCharge();session()->flash('success',__('application.additional_charge_type_saved_481124c2'));};
$toggleCharge=function(int $id){abort_unless(auth()->user()->can('additional_charge_types.manage'),403);$c=AdditionalChargeType::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->where('company_id',auth()->user()->company_id)->findOrFail($id);$c->update(['is_active'=>!$c->is_active]);$this->audit($c,$c->is_active?'activated':'deactivated',['name'=>$c->name]);};
?>
